uintptr_t base() { return (uintptr_t)GetModuleHandleW(nullptr); }

void L(const char* fmt, ...) {
    char buf[1024];   // 1024: the [TP] probe lines carry 16 %.4f values plus a tag; 256 truncated them
    va_list ap; va_start(ap, fmt);
    _vsnprintf_s(buf, sizeof(buf), _TRUNCATE, fmt, ap);
    va_end(ap);
    printf("%s", buf);
    OutputDebugStringA(buf);
    // Also append to a per-process file, flushed each line, so the trail survives a crash.
    static FILE* volatile f = nullptr;
    // F18: first open is gated so two threads' first calls cannot both _fsopen(_SH_DENYWR) - the loser
    // would fail, leak nothing useful and could null `f`. 0 = closed, 1 = opening, 2 = open.
    static volatile LONG s_openState = 0;
    if (!f && InterlockedCompareExchange(&s_openState, 1, 0) != 0) {
        while (s_openState == 1) Sleep(0);   // another thread is opening: wait, then use its handle
    } else if (!f) {
        char name[64];
        wsprintfA(name, "phase1_log_%u.txt", GetCurrentProcessId());
        const char* path = Paths::LogPath(name);
        // _SH_DENYWR: deny other writers but allow readers, so the log is readable live (no quit needed).
        f = _fsopen(path, "w", _SH_DENYWR);
        if (!f) Paths::NoteOpenFailure(path);   // visible on the debugger + beacon, not silently absent
        // Task 0.2: [Build] is the first line of every phase1_log_<pid>.txt. "w" truncates, and nothing
        // is written to `f` before this block, so this is byte 0 of a fresh file (and of the first file
        // of each process, since `f` is static and opened once).
        if (f) {
            char buildLine[256];
            if (AC4Coop_FormatBuildLine(buildLine, (int)sizeof(buildLine)) > 0) {
                fputs(buildLine, f);
                fflush(f);
            }
            // Second line, before any [Paths]-dependent decision is logged: says which ini was used and
            // where the logs go, so a tester's file answers "did it read my ini?" on its own.
            char pathsLine[1024];
            if (Paths::Describe(pathsLine, sizeof(pathsLine)) > 0) {
                fputs(pathsLine, f);
                fflush(f);
            }
        }
        InterlockedExchange(&s_openState, f ? 2 : 0);   // a failed open may be retried, as before
    }
    if (f) { fputs(buf, f); fflush(f); }
}

