    if (ground) { s_offSince = 0; if (!s_groundSince) s_groundSince = now; }
    else { s_groundSince = 0; if (!s_offSince) s_offSince = now; }
    const bool want = s_in ? (ground || now - s_offSince < 400) : (ground && now - s_groundSince >= 300);
