    if (rxUs - s_offWinUs > 2000000) { InterlockedExchange64((volatile LONGLONG*)&s_offPrev, s_offCur); InterlockedExchange64((volatile LONGLONG*)&s_offCur, INT64_MAX); s_offWinUs = rxUs; }
